import{z as s,x as l,o as B,c as m,q as r,j as n,D as t,d as e,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"事件前的仓位管理","description":"","frontmatter":{"title":"事件前的仓位管理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-event-positioning.md","filePath":"quant/omm-event-positioning.md","lastUpdated":1791413859000}'),p={name:"quant/omm-event-positioning.md"};function d(u,a,h,D,f,C){const i=l("Mermaid");return B(),m("div",null,[a[2]||(a[2]=r('<h1 id="事件前的仓位管理" tabindex="-1">事件前的仓位管理 <a class="header-anchor" href="#事件前的仓位管理" aria-label="Permalink to &quot;事件前的仓位管理&quot;">​</a></h1><div class="epigraph"><p>跳空平时是尾部，事件周是日程：把风险从「可能发生」改写成「何时、多大、怎么扛」，是事件前管理的全部。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives 波动率与事件风险相关章节；事件流程据做市实务整理</footer></div><p><a href="/quant/omm-hedge-execution">上一课</a>把对冲写成执行规则，规则表里已经出现了「事件前补」这一类。本课把它展开：财报、议息、数据与到期日把跳空变成日历上的确定项，<a href="/quant/overnight-gap-hedge">隔夜跳空</a> 的损失期望在事件夜放大数倍。仓位管理要回答：事件前减什么、报价怎么改、事件窗怎么锁、事后怎么恢复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>事件改写风险的三种方式。其一，分布变形：股价的条件分布从近似连续变成「小动或大跳」的双峰，Gamma 在两次再平衡之间的保护失效，\\(\\tfrac12\\Gamma(\\Delta S)^2\\) 按跳空幅度平方计价。其二，相关性失效：对冲工具与持仓在跳空里脱钩，期货对个股账本的保护打折。其三，流动性收缩：事件前后价差扩到平时数倍，<a href="/quant/omm-hedge-execution">对冲执行</a> 的参与率上限形同虚设。</p><p><span class="marginnote">直觉类比：Gamma 再平衡像一把伞，平时的小阵雨撑得住；事件夜是大浪打来，伞来不及开合。所以事件前的正确动作是换雨衣——提前减仓、加宽价差、预留对冲，而不是更用力地撑伞（提高再平衡频率）。</span></p><p>做市台的特有问题是报价暴露：事件前客户单边需求最猛——买保护的人集中买看跌。报价不变等于用自家库存接走市场想扔掉的尾部。</p><h3 id="事件台账" tabindex="-1">事件台账 <a class="header-anchor" href="#事件台账" aria-label="Permalink to &quot;事件台账&quot;">​</a></h3><p>风险系统里先建事件台账：每条事件带时间窗、影响标的、预期幅度与限制级别。预期幅度有市场价格可用：到期横跨事件的平值跨式价格约 \\(0.8\\,S\\sigma\\sqrt{\\tau}\\)，大致就是市场定价的隐含移动；与内部情景对表，是事件前最便宜的压力测试。限制级别决定动作：三级只收紧限额，二级加宽价差并缩报价规模，一级收缩到核心档并暂停裸卖新仓。</p><p><span class="marginnote">「减仓」要有明细：把净 Gamma 从 2 万减到 5 千，落到执行价上意味着先平贴值到期、再平远期——事件 Gamma 几乎全住在近月。只按总量减、不按期限减的台，事件夜发现减掉的恰是最不危险的仓位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件前一周：盘点近月到期与事件的重叠，<a href="/quant/pin-risk">Pin risk</a> 高危执行价提前观察；数字与触碰类暴露单独清点，见 <a href="/quant/digital-options">数字期权</a> 与 <a href="/quant/barrier-monitoring">障碍监控</a>。事件前一日：完成减仓与对冲，收盘预留按「事件夜 Charm」而非普通隔夜计算；报价切换到事件档价差。事件窗内：系统锁单向改仓，人工只留对冲与砍仓；已对冲完的账本什么都不做也是策略——事件后的波动回落会惩罚在恐慌顶点买回 Gamma 的人。事件后一日：事件溢价消失使近月隐波下行，<a href="/quant/omm-vol-position-ledger">期限桶账本</a> 的近月空头回收利润；恢复报价档级、复盘台账，把「预期 vs 实际幅度」写进事件库。</p><p><span class="marginnote">数字实例：股价 100、事件横跨一周（\\(\\tau=1/52\\)）、隐波 40%，平值跨式给出的隐含移动约 \\(0.8\\times100\\times0.4\\times\\sqrt{1/52}\\approx4.4\\)，即市场认为事件夜约 ±4.4% 的跳空。把它与内部情景对表：内部取 ±6% 就要想清楚为什么比市场悲观——对表本身就是最便宜的压力测试。</span></p>',13)),(B(),n(A,null,{default:t(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BA%8B%E4%BB%B6%E5%8F%B0%E8%B4%A6%20%E6%97%B6%E9%97%B4%E7%AA%97%20%E5%BD%B1%E5%93%8D%E9%9D%A2%22%5D%20--%3E%20B%7B%22%E9%99%90%E5%88%B6%E7%BA%A7%E5%88%AB%22%7D%0A%20%20B%20--%3E%7C%E4%B8%89%E7%BA%A7%7C%20C%5B%22%E6%94%B6%E7%B4%A7%E9%99%90%E9%A2%9D%22%5D%0A%20%20B%20--%3E%7C%E4%BA%8C%E7%BA%A7%7C%20D%5B%22%E5%8A%A0%E5%AE%BD%E4%BB%B7%E5%B7%AE%20%E7%BC%A9%E8%A7%84%E6%A8%A1%22%5D%0A%20%20B%20--%3E%7C%E4%B8%80%E7%BA%A7%7C%20E%5B%22%E6%94%B6%E7%BC%A9%E5%88%B0%E6%A0%B8%E5%BF%83%E6%A1%A3%20%E5%81%9C%E8%A3%B8%E5%8D%96%22%5D%0A%20%20C%20--%3E%20F%5B%22%E4%BA%8B%E4%BB%B6%E7%AA%97%20%E9%94%81%E5%8D%95%E5%90%91%E6%94%B9%E4%BB%93%22%5D%0A%20%20D%20--%3E%20F%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%5B%22%E4%BA%8B%E4%BB%B6%E5%90%8E%20%E6%B3%A2%E5%8A%A8%E5%9B%9E%E8%90%BD%20%E5%A4%8D%E7%9B%98%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20G%20--%3E%20A%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("为什么按期限分层减仓：事件损失几乎全由近月 Gamma 承担，远月 Vega 只是标记波动。反过来，完全清仓不是最优：事件溢价是波动卖方的收入之一，长期全回避等于放弃整块业务；正确的问题是「在限额内拿多少事件风险」，答案由 "),E("a",{href:"/quant/omm-greeks-limits"},"情景限额"),e(" 给出，而不是由胆量给出。报价侧的机制同理：加宽是在收费承接尾部，撤单是把客户推给对手——义务做市品种的协议会限制后者，自由度边界要事先知道。")],-1)),a[5]||(a[5]=E("p",null,"不这么做会错在哪：不建台账的台靠记忆管事件，一次多事件重叠日（议息撞到期、财报撞指数再平衡）就能让两个「各自没事」的账本合计击穿限额；事件后不降档的台，则一直用事件价差做生意，把客户全赶到对手那里。",-1)),(B(),n(A,null,{default:t(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%BA%8B%E4%BB%B6%E5%A4%9C%20%E8%B7%B3%E7%A9%BA%E5%8F%91%E7%94%9F%22%5D%20--%3E%20G%5B%22%E8%BF%91%E6%9C%88%20Gamma%20%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20E%20--%3E%20V%5B%22%E8%BF%9C%E6%9C%88%20Vega%20%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20G%20--%3E%20G1%5B%22%E5%86%8D%E5%B9%B3%E8%A1%A1%E4%BF%9D%E6%8A%A4%E5%A4%B1%E6%95%88%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E6%8D%9F%E5%A4%B1%E6%8C%89%E8%B7%B3%E7%A9%BA%E5%B9%B3%E6%96%B9%E8%AE%A1%E4%BB%B7%22%5D%0A%20%20V%20--%3E%20V1%5B%22%E9%9A%90%E6%B3%A2%E6%B0%B4%E5%B9%B3%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20V1%20--%3E%20V2%5B%22%E5%8F%AA%E6%98%AF%E6%A0%87%E8%AE%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20G2%20--%3E%20C%5B%22%E5%87%8F%E4%BB%93%E5%85%88%E8%BF%91%E6%9C%88%20%E5%90%8E%E8%BF%9C%E6%9C%88%22%5D%0A%20%20V2%20--%3E%20C%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>台账只覆盖已知日历：地缘冲突、停牌与监管行动没有预告，事件管理对它们无效，兜底仍是 <a href="/quant/omm-greeks-limits">限额</a> 与资本。隐含移动是市场共识不是预测，把它当内部情景会自我循环；事件溢价的规模随品种与年份漂移，事件库要滚动更新而不是一次性标定。最后，事件是 <a href="/quant/vix-term-structure-trade">波动率期限结构</a> 上的齿：连续处理事件（把每个事件当一次小展期）与离散处理（事件前后切换档级）是两种风格，混用会让期限桶的盈亏解释失去一致性。</p><p><span class="marginnote">常见误区：初学者容易以为事件前「全部清仓」最安全。实际上事件溢价是波动卖方收入的一部分，长期全回避等于放弃整块业务；正确的问题是「在限额内拿多少事件风险」，答案由情景限额给出，而不是由胆量给出。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件把跳空变成日程：分布双峰、对冲脱钩、流动性收缩，三条都要进预案。</li><li>事件台账带时间窗与限制级别；跨式价格给出市场定价的隐含移动作对表基准。</li><li>减仓按期限分层：事件 Gamma 住近月，只减总量的台减错了仓位。</li><li>加宽是收费承接尾部，撤单是最后手段；义务协议限定自由度。</li><li>事件后波动回落要降档恢复并复盘台账；未知事件靠限额兜底。</li><li>出处：据 Hull, <em>Options, Futures, and Other Derivatives</em>；事件台账与档级实务据期权做市运营整理。</li></ul>',5))])}const c=s(p,[["render",d]]);export{g as __pageData,c as default};
